	// ---------------------------------------------------------------- CoR party (opt-in)

	private String passphrase()
	{
		String p = config.partyPassphrase() == null ? "" : config.partyPassphrase().trim();
		return p.isEmpty() ? CorClanConfig.DEFAULT_PARTY_PASSPHRASE : p;
	}

	/** In RuneLite's party with our passphrase. */
	private boolean inCorParty()
	{
		return partyService.isInParty() && passphrase().equals(partyService.getPartyPassphrase());
	}

	private boolean partyActive()
	{
		return inCorParty() && partyService.getLocalMember() != null;
	}

	/**
	 * Panel button: joins the CoR party, or leaves it if we are in it. The only way the plugin ever changes
	 * the party, so it never joins on its own (RuneLite asks plugins not to auto-join parties).
	 */
	private void toggleCorParty()
	{
		clientThread.invokeLater(() ->
		{
			if (inCorParty())
			{
				leaveCorParty();
			}
			else
			{
				log.debug("Joining the CoR party");
				partyService.changeParty(passphrase());
			}
			updateGzView();
			refreshPanel();
		});
	}

	private void leaveCorParty()
	{
		stopSharingLocation();
		clearPartyLocations();
		if (inCorParty())
		{
			partyService.changeParty(null);
		}
	}

	private String partyStatus()
	{
		if (!partyService.isInParty())
		{
			return "CoR party: not joined";
		}
		if (!inCorParty())
		{
			return "CoR party: you are in another party";
		}
		if (partyService.getLocalMember() == null)
		{
			return "CoR party: connecting";
		}
		int others = Math.max(0, partyService.getMembers().size() - 1);
		return "CoR party: on, " + others + (others == 1 ? " other member" : " other members");
	}

	/** The sender of a CoR message, or null if it is us, unknown, or we are not in the CoR party. */
	private PartyMember sender(long memberId)
	{
		if (!partyActive())
		{
			return null;
		}
		PartyMember member = partyService.getMemberById(memberId);
		PartyMember local = partyService.getLocalMember();
		if (member == null || member.getDisplayName() == null || (local != null && local.getMemberId() == memberId))
		{
			return null;
		}
		return member;
	}

	/** Our clan's rank for a name, or null if they are not in it. Client thread. */
	private ClanRank clanRankOf(String name)
	{
		ClanSettings settings = client.getClanSettings();
		if (settings == null || name == null)
		{
			return null;
		}
		String key = MemberCosmetics.key(name);
		for (ClanMember m : settings.getMembers())
		{
			if (key.equals(MemberCosmetics.key(m.getName())))
			{
				return m.getRank();
			}
		}
		return null;
	}

	private static boolean isStaff(ClanRank rank)
	{
		return rank != null && rank.getRank() >= ClanRank.ADMINISTRATOR.getRank();
	}

	@Subscribe
	public void onPartyChanged(PartyChanged event)
	{
		clientThread.invokeLater(() ->
		{
			clearPartyLocations();
			glowPicks.clearPartyPicks();
			lavaAura.clearPartyPicks();
			updateGzView();
			// we just joined: the party gets our counts and glow, and staff their lists
			sendGzSoon = true;
			sendStaffSoon = true;
			sendGlowSoon = true;
			refreshPanel();
		});
	}

	@Subscribe
	public void onUserJoin(UserJoin event)
	{
		// the newcomer needs the party's counts and the staff settings
		clientThread.invokeLater(() ->
		{
			PartyMember local = partyService.getLocalMember();
			if (local != null && local.getMemberId() != event.getMemberId())
			{
				sendGzSoon = true;
				sendStaffSoon = true;
				sendGlowSoon = true;
			}
			refreshPanel();
		});
	}

	@Subscribe
	public void onUserPart(UserPart event)
	{
		clientThread.invokeLater(() ->
		{
			if (partyLocations.remove(event.getMemberId()) != null)
			{
				redrawMap();
			}
			partyNames.remove(event.getMemberId());
			glowPicks.removePartyMember(event.getMemberId());
			lavaAura.removePartyMember(event.getMemberId());
			partySeen.remove(event.getMemberId());
			refreshPanel();
		});
	}

	/**
	 * Every 10 seconds: sends our gz counts when someone joined, or when they changed and the last send was
	 * {@link #GZ_SEND_MILLIS} ago, and the staff lists when asked.
	 */
	@Schedule(period = 10, unit = ChronoUnit.SECONDS)
	public void partyTimer()
	{
		clientThread.invokeLater(() ->
		{
			if (!partyActive())
			{
				return;
			}
			long now = System.currentTimeMillis();
			String me = localPlayerName();
			if (me != null && (sendGzSoon || (gzDirty && now - lastGzSent >= GZ_SEND_MILLIS)))
			{
				// only our own numbers: RuneLite does not allow crowdsourcing data about other players
				partyGz.rollWeek(tracker.getWeekStart());
				partyService.send(partyGz.message(me, tracker.getWeekly(), tracker.getAllTime()));
				gzDirty = false;
				sendGzSoon = false;
				lastGzSent = now;
			}
			if (sendStaffSoon)
			{
				sendStaffSettings();
				sendStaffSoon = false;
			}
			if (sendGlowSoon)
			{
				// rank glow picks and dev glow picks travel together; each side ignores the other's ids
				List<String> picks = new ArrayList<>(glowPicks.localPicks());
				picks.addAll(lavaAura.localPicks());
				partyService.send(new CorGlowPicks(picks));
				sendGlowSoon = false;
			}
		});
	}

	// party messages arrive on the websocket thread; all state lives on the client thread

	@Subscribe
	public void onCorGzCounts(CorGzCounts msg)
	{
		clientThread.invokeLater(() ->
		{
			PartyMember from = sender(msg.getMemberId());
			if (from == null || clanRankOf(from.getDisplayName()) == null)
			{
				return;
			}
			partyGz.rollWeek(tracker.getWeekStart());
			if (partyGz.merge(displayName(from.getDisplayName()), msg, System.currentTimeMillis()))
			{
				persistStats();
				updateGzView();
				refreshPanel();
			}
		});
	}

	@Subscribe
	public void onCorLocation(CorLocation msg)
	{
		clientThread.invokeLater(() ->
		{
			PartyMember from = sender(msg.getMemberId());
			if (from == null || clanRankOf(from.getDisplayName()) == null)
			{
				return;
			}
			long id = msg.getMemberId();
			if (msg.isStopped())
			{
				partyLocations.remove(id);
				partySeen.remove(id);
			}
			else
			{
				partyLocations.put(id, msg);
				partyNames.put(id, from.getDisplayName());
				partySeen.put(id, System.currentTimeMillis());
			}
			redrawMap();
		});
	}

	/** A party member's glow picks; drawn only as far as their clan rank (as we see it) allows. */
	@Subscribe
	public void onCorGlowPicks(CorGlowPicks msg)
	{
		clientThread.invokeLater(() ->
		{
			PartyMember from = sender(msg.getMemberId());
			if (from == null || clanRankOf(from.getDisplayName()) == null)
			{
				return;
			}
			glowPicks.setPartyPicks(msg.getMemberId(), from.getDisplayName(), msg.getGlows());
			lavaAura.setPartyPicks(msg.getMemberId(), from.getDisplayName(), msg.getGlows());
		});
	}

	@Subscribe
	public void onCorStaffSettings(CorStaffSettings msg)
	{
		clientThread.invokeLater(() ->
		{
			PartyMember from = sender(msg.getMemberId());
			if (from == null || !isStaff(clanRankOf(from.getDisplayName())))
			{
				return;
			}
			String members = msg.getMemberIcons() == null ? "" : msg.getMemberIcons();
			String ranks = msg.getRankIcons() == null ? "" : msg.getRankIcons();
			if (members.length() > MAX_STAFF_TEXT || ranks.length() > MAX_STAFF_TEXT
				|| msg.getUpdatedAt() > System.currentTimeMillis() + MAX_CLOCK_SKEW_MILLIS)
			{
				return;
			}
			long ours = staffUpdatedAt();
			if (msg.getUpdatedAt() > ours)
			{
				log.debug("Staff icon settings from {}", from.getDisplayName());
				lastRemoteMemberIcons = normalizeStaffText(members);
				lastRemoteRankIcons = normalizeStaffText(ranks);
				configManager.setConfiguration(CorClanConfig.GROUP, STAFF_UPDATED_KEY, String.valueOf(msg.getUpdatedAt()));
				configManager.setConfiguration(CorClanConfig.GROUP, "clanMemberIcons", members);
				configManager.setConfiguration(CorClanConfig.GROUP, "clanRankIcons", ranks);
				rebuildCosmetics();
				client.refreshChat();
			}
			else if (msg.getUpdatedAt() < ours)
			{
				// they have an older list: if we are staff, ours goes out on the next timer tick
				sendStaffSoon = true;
			}
		});
	}

	/** Client thread: a staff list was edited in this client's settings. */
	private void onStaffEdit()
	{
		if (!isStaff(clanRankOf(localPlayerName())))
		{
			return;
		}
		configManager.setConfiguration(CorClanConfig.GROUP, STAFF_UPDATED_KEY, String.valueOf(System.currentTimeMillis()));
		sendStaffSettings();
	}

	/** Client thread: staff send their lists to the party. */
	private void sendStaffSettings()
	{
		long updatedAt = staffUpdatedAt();
		if (!partyActive() || updatedAt == 0 || !isStaff(clanRankOf(localPlayerName())))
		{
			return;
		}
		partyService.send(new CorStaffSettings(updatedAt, config.clanMemberIcons(), config.clanRankIcons()));
	}

	private long staffUpdatedAt()
	{
		String raw = configManager.getConfiguration(CorClanConfig.GROUP, STAFF_UPDATED_KEY);
		try
		{
			return raw == null ? 0L : Long.parseLong(raw);
		}
		catch (NumberFormatException ex)
		{
			return 0L;
		}
	}

	private static String normalizeStaffText(String text)
	{
		return text == null ? "" : text.replace("\r\n", "\n").trim();
	}

	// ---------------------------------------------------------------- clan map (through the CoR party)

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		holyAura.onClientTick();
		lavaAura.onClientTick();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		holyAura.onGameTick();
		tickLocation();
		// the Owner glow section appears once your clan rank has loaded (and goes if it changes)
		if (panelShowsOwner != ClanRank.OWNER.equals(glowPicks.localRank()) || panelShowsDev != isDev())
		{
			refreshPanel();
		}
	}

	/** Client thread, every game tick: shares our position with the CoR party while "Share my location" is on. */
	private void tickLocation()
	{
		Player me = client.getLocalPlayer();
		if (client.getGameState() != GameState.LOGGED_IN || me == null)
		{
			return;
		}
		boolean inWilderness = client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) == 1;
		LocationRules.Decision decision = LocationRules.decide(inWilderness, client.isInInstancedRegion(), config.shareInWilderness());
		setMapState(MapState.of(config.shareLocation(), inCorParty(), partyActive(), decision));
		if (mapState != MapState.SHARING)
		{
			stopSharingLocation();
			return;
		}

		int every = Math.max(LOCATION_TICKS, partyService.getMembers().size() / 2);
		// the first position goes out right away, so your own marker appears as soon as you turn sharing on
		if (selfLocation != null && ++locationTick < every)
		{
			return;
		}
		locationTick = 0;
		expirePartyLocations();

		WorldPoint here = me.getWorldLocation();
		CorLocation loc = new CorLocation(client.getWorld(), here.getX(), here.getY(), here.getPlane(), inWilderness, false);
		long now = System.currentTimeMillis();
		boolean moved = !loc.equals(selfLocation);
		if (moved || now - lastLocationSent >= LOCATION_HEARTBEAT_MILLIS)
		{
			partyService.send(loc);
			lastLocationSent = now;
		}
		selfLocation = loc;
		if (moved)
		{
			redrawMap();
		}
	}

	/** Client thread: remembers the clan map's state, and says in chat when it starts sharing or pauses. */
	private void setMapState(MapState next)
	{
		if (next == mapState)
		{
			return;
		}
		mapState = next;
		if (next.announcement != null)
		{
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", next.announcement, null);
		}
		refreshPanel();
	}

	/** Client thread: tells the party we stopped and hides the map. Safe to call when not sharing. */
	private void stopSharingLocation()
	{
		if (selfLocation == null)
		{
			return;
		}
		selfLocation = null;
		locationTick = 0;
		lastLocationSent = 0;
		if (partyActive())
		{
			partyService.send(new CorLocation(0, 0, 0, 0, false, true));
		}
		mapPoints.clear();
	}

	private void expirePartyLocations()
	{
		long cutoff = System.currentTimeMillis() - LOCATION_EXPIRY_MILLIS;
		if (partySeen.entrySet().removeIf(e -> e.getValue() < cutoff))
		{
			partyLocations.keySet().retainAll(partySeen.keySet());
			redrawMap();
		}
	}

	/** Only people who share can see others. */
	private void redrawMap()
	{
		if (selfLocation == null)
		{
			mapPoints.clear();
			return;
		}
		Map<String, CorLocation> others = new TreeMap<>();
		partyLocations.forEach((id, loc) -> others.put(partyNames.getOrDefault(id, "Clanmate"), loc));
		mapPoints.update(others, selfLocation);
		if (others.size() != mapCount)
		{
			mapCount = others.size();
			refreshPanel();
		}
	}

	private void clearPartyLocations()
	{
		partyLocations.clear();
		partyNames.clear();
		partySeen.clear();
		mapPoints.clear();
	}
}

package com.corclan.clan;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.TreeMap;

/**
 * Clan members grouped by in-game clan rank, highest rank first; within a rank, online members
 * first, then by name. Pure Java so it can be unit tested; the plugin feeds it from ClanSettings.
 */
public final class ClanRoster
{
	/** One clan member as the roster needs it. */
	public static final class Member
	{
		public final String name;
		/** RuneLite ClanRank number: 126 owner, 125 deputy owner, 100 admin, ... */
		public final int rank;
		/** The clan's own title for that rank, e.g. "Captain"; null if the game didn't give one */
		public final String title;
		public final boolean online;

		public Member(String name, int rank, String title, boolean online)
		{
			this.name = name;
			this.rank = rank;
			this.title = title;
			this.online = online;
		}

		@Override
		public boolean equals(Object o)
		{
			if (!(o instanceof Member))
			{
				return false;
			}
			Member m = (Member) o;
			return rank == m.rank && online == m.online && name.equals(m.name) && Objects.equals(title, m.title);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(name, rank, title, online);
		}
	}

	/** Everyone holding one rank. */
	public static final class RankGroup
	{
		public final int rank;
		public final String title;
		public final List<Member> members;

		RankGroup(int rank, String title, List<Member> members)
		{
			this.rank = rank;
			this.title = title;
			this.members = Collections.unmodifiableList(members);
		}

		public int onlineCount()
		{
			return (int) members.stream().filter(m -> m.online).count();
		}

		@Override
		public boolean equals(Object o)
		{
			if (!(o instanceof RankGroup))
			{
				return false;
			}
			RankGroup g = (RankGroup) o;
			return rank == g.rank && Objects.equals(title, g.title) && members.equals(g.members);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(rank, title, members);
		}
	}

	private ClanRoster()
	{
	}

	/** @return rank groups, highest rank first; empty if there are no members */
	public static List<RankGroup> group(List<Member> members)
	{
		Map<Integer, List<Member>> byRank = new TreeMap<>(Comparator.reverseOrder());
		for (Member m : members)
		{
			if (m != null && m.name != null && !m.name.isEmpty())
			{
				byRank.computeIfAbsent(m.rank, r -> new ArrayList<>()).add(m);
			}
		}

		List<RankGroup> groups = new ArrayList<>();
		byRank.forEach((rank, list) ->
		{
			list.sort(Comparator.comparing((Member m) -> !m.online)
				.thenComparing(m -> m.name, String.CASE_INSENSITIVE_ORDER));
			groups.add(new RankGroup(rank, titleOf(rank, list), list));
		});
		return groups;
	}

	private static String titleOf(int rank, List<Member> members)
	{
		for (Member m : members)
		{
			if (m.title != null && !m.title.isEmpty())
			{
				return m.title;
			}
		}
		return "Rank " + rank;
	}

	public static int total(List<RankGroup> groups)
	{
		return groups.stream().mapToInt(g -> g.members.size()).sum();
	}

	public static int online(List<RankGroup> groups)
	{
		return groups.stream().mapToInt(RankGroup::onlineCount).sum();
	}
}

package com.corclan.clan;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;

/**
 * Lays the clan's rank groups out as the CoR org chart. Two chains of boxes, top to bottom:
 * <ul>
 * <li>staff: three tiers of leadership ranks, matched by title</li>
 * <li>competitive: the letter tiers (S = Soul ... F = Gnome child) above the Gem League entry
 * ranks (Zenyte ... Opal) players start in; players graduate from the gems into the letters</li>
 * </ul>
 * Ranks are matched by their in-game title, since clans rename ranks freely. Every listed rank is
 * shown, vacant if nobody holds it. Anything left over goes into {@link Chart#others}.
 */
public final class OrgChart
{
	/** One tier's definition: a label, its rank titles in display order, and optional letter grades. */
	static final class TierDef
	{
		final String name;
		final List<String> titles;
		/** one letter per title (e.g. "SABCDEF"), or null for ungraded tiers */
		final String grades;

		TierDef(String name, String... titles)
		{
			this(name, null, Arrays.asList(titles));
		}

		private TierDef(String name, String grades, List<String> titles)
		{
			if (grades != null && grades.length() != titles.size())
			{
				throw new IllegalArgumentException(name + ": need one grade per title");
			}
			this.name = name;
			this.titles = titles;
			this.grades = grades;
		}

		static TierDef graded(String name, String grades, String... titles)
		{
			return new TierDef(name, grades, Arrays.asList(titles));
		}
	}

	/** The CoR staff hierarchy, top tier first. Edit here to change the chart. */
	static final List<TierDef> STAFF_TIERS = Arrays.asList(
		new TierDef("Owners", "Owner", "Deputy Owner"),
		new TierDef("Staff", "Marshal", "General", "Brigadier", "Colonel", "Administrator"),
		new TierDef("Hall of Fame", "Major", "Goon", "Executive", "Short green guy", "Hero"));

	/** Entry league, highest first: players start at Opal and work up to Zenyte. */
	static final TierDef GEM_LEAGUE = new TierDef("Gem League",
		"Zenyte", "Onyx", "Dragonstone", "Diamond", "Ruby", "Emerald", "Sapphire", "Opal");

	/** Competitive bracket, S tier first (placeholder titles; edit here). Earned by gz count. */
	static final TierDef LETTER_TIERS = TierDef.graded("Challenger League", "SABCDEF",
		"Soul", "Achiever", "Beast", "Competitor", "Dragon", "Elite", "Gnome child");

	/** One rank slot in a tier: the title as charted, and whoever holds it (empty = vacant). */
	public static final class Slot
	{
		/** letter grade for the competitive tiers ("S", "A", ...), otherwise null */
		public final String grade;
		public final String title;
		public final List<ClanRoster.Member> members;

		Slot(String grade, String title, List<ClanRoster.Member> members)
		{
			this.grade = grade;
			this.title = title;
			this.members = Collections.unmodifiableList(members);
		}

		public int onlineCount()
		{
			return (int) members.stream().filter(m -> m.online).count();
		}
	}

	public static final class Tier
	{
		public final String name;
		public final List<Slot> slots;

		Tier(String name, List<Slot> slots)
		{
			this.name = name;
			this.slots = Collections.unmodifiableList(slots);
		}
	}

	public static final class Chart
	{
		/** leadership tiers, top first */
		public final List<Tier> staff;
		/** letter tiers (when Soul and Gnome child are set up) above the Gem League */
		public final List<Tier> competitive;
		/** rank groups that aren't in any tier, highest rank first */
		public final List<ClanRoster.RankGroup> others;

		Chart(List<Tier> staff, List<Tier> competitive, List<ClanRoster.RankGroup> others)
		{
			this.staff = Collections.unmodifiableList(staff);
			this.competitive = Collections.unmodifiableList(competitive);
			this.others = Collections.unmodifiableList(others);
		}
	}

	private OrgChart()
	{
	}

	/**
	 * @param groups     the roster from {@link ClanRoster#group}, highest rank first
	 * @param rankTitles every rank the clan has set up (rank number to title), including ranks
	 *                   nobody holds (their titles are shown as the game spells them)
	 */
	public static Chart build(List<ClanRoster.RankGroup> groups, Map<Integer, String> rankTitles)
	{
		// all known ranks: the clan's setup, plus any rank a member holds that the setup didn't list
		Map<Integer, String> ranks = new TreeMap<>(Collections.reverseOrder());
		ranks.putAll(rankTitles);
		for (ClanRoster.RankGroup g : groups)
		{
			ranks.putIfAbsent(g.rank, g.title);
		}

		Map<Integer, ClanRoster.RankGroup> byRank = new LinkedHashMap<>();
		for (ClanRoster.RankGroup g : groups)
		{
			byRank.put(g.rank, g);
		}

		Set<Integer> charted = new HashSet<>();
		List<Tier> staff = new ArrayList<>();
		for (TierDef def : STAFF_TIERS)
		{
			staff.add(titledTier(def, ranks, byRank, charted));
		}

		List<Tier> competitive = Arrays.asList(
			titledTier(LETTER_TIERS, ranks, byRank, charted),
			titledTier(GEM_LEAGUE, ranks, byRank, charted));

		List<ClanRoster.RankGroup> others = new ArrayList<>();
		for (ClanRoster.RankGroup g : groups)
		{
			if (!charted.contains(g.rank))
			{
				others.add(g);
			}
		}
		return new Chart(staff, competitive, others);
	}

	/** A tier whose slots are fixed titles; each slot gathers every rank number carrying that title. */
	private static Tier titledTier(TierDef def, Map<Integer, String> ranks, Map<Integer, ClanRoster.RankGroup> byRank,
		Set<Integer> charted)
	{
		List<Slot> slots = new ArrayList<>();
		for (int i = 0; i < def.titles.size(); i++)
		{
			String title = def.titles.get(i);
			String grade = def.grades == null ? null : String.valueOf(def.grades.charAt(i));
			List<ClanRoster.Member> members = new ArrayList<>();
			String shownTitle = title;
			for (Map.Entry<Integer, String> rank : ranks.entrySet())
			{
				if (!charted.contains(rank.getKey()) && normalize(rank.getValue()).equals(normalize(title)))
				{
					shownTitle = rank.getValue();
					charted.add(rank.getKey());
					ClanRoster.RankGroup g = byRank.get(rank.getKey());
					if (g != null)
					{
						members.addAll(g.members);
					}
				}
			}
			slots.add(new Slot(grade, shownTitle, members));
		}
		return new Tier(def.name, slots);
	}

	/** Case, spacing and the common "Marshall" spelling don't matter when matching titles. */
	static String normalize(String title)
	{
		String t = title == null ? "" : title.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
		return t.equals("marshall") ? "marshal" : t;
	}
}

package com.corclan.glow;

import com.corclan.CorClanConfig;
import java.util.Collection;
import java.util.EnumSet;
import java.util.Set;

/**
 * The parts of Lavasockz's aura ({@link LavaAura}), each switchable by Lavasockz only: hidden settings, set
 * from the "Dev glow" section of the CoR side panel (shown only to Lavasockz) or with ::devglow. Picks travel
 * through the CoR party inside the same message as the rank glow picks, so other plugin users see what he
 * chose. Separate from {@link GlowEffect}, which is unlocked by clan rank, not by name.
 */
public enum DevGlow
{
	MOLTEN_OUTLINE("dev_molten_outline", "devGlowOutline", "lava", "Molten outline"),
	ZAMORAK_FLAMES("dev_zamorak_flames", "devGlowFlames", "flames", "Flames of Zamorak");

	/** sent to other party members; never change one once released */
	public final String id;
	/** the hidden checkbox's key in {@link CorClanConfig} */
	public final String configKey;
	/** its name in ::devglow, e.g. ::devglow flames off */
	public final String shortName;
	/** shown next to its checkbox in the side panel */
	public final String label;

	DevGlow(String id, String configKey, String shortName, String label)
	{
		this.id = id;
		this.configKey = configKey;
		this.shortName = shortName;
		this.label = label;
	}

	public static boolean picked(CorClanConfig config, DevGlow glow)
	{
		switch (glow)
		{
			case MOLTEN_OUTLINE:
				return config.devGlowOutline();
			case ZAMORAK_FLAMES:
				return config.devGlowFlames();
			default:
				return false;
		}
	}

	/** The part called {@code name} in ::devglow (any case), or null. */
	public static DevGlow byShortName(String name)
	{
		for (DevGlow glow : values())
		{
			if (glow.shortName.equalsIgnoreCase(name))
			{
				return glow;
			}
		}
		return null;
	}

	public static boolean isConfigKey(String key)
	{
		for (DevGlow glow : values())
		{
			if (glow.configKey.equals(key))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * What the wearer shows.
	 * @param picks the ids they shared through the party (rank glow ids mixed in are ignored), or null if they
	 *              shared none: then everything shows
	 */
	public static Set<DevGlow> active(Collection<String> picks)
	{
		if (picks == null)
		{
			return EnumSet.allOf(DevGlow.class);
		}
		Set<DevGlow> active = EnumSet.noneOf(DevGlow.class);
		for (DevGlow glow : values())
		{
			if (picks.contains(glow.id))
			{
				active.add(glow);
			}
		}
		return active;
	}
}

package com.corclan.glow;

import java.util.Collection;
import java.util.Collections;
import java.util.EnumSet;
import java.util.Set;
import net.runelite.api.clan.ClanRank;

/**
 * Every glow effect a clan member can show on themselves. Each needs a clan rank: that rank or any
 * higher one unlocks it. The Owner's effects are hidden settings, switched in the side panel (shown only
 * to the Owner) or with ::myglow, so the rest of the clan never sees them. Picks are shared through the
 * CoR party so other plugin users see them. The viewer always checks the wearer's real clan rank, so
 * picking a locked effect (or a forged pick) shows nothing.
 */
public enum GlowEffect
{
	GOLD_OUTLINE("gold_outline", "glowGoldOutline", "outline", "Gold outline", ClanRank.OWNER),
	STORM_CLOUD("storm_cloud", "glowStormCloud", "cloud", "Storm cloud", ClanRank.OWNER),
	LIGHTNING_STRIKES("lightning_strikes", "glowLightningStrikes", "strikes", "Lightning strikes", ClanRank.OWNER),
	SHOCKS("shocks", "glowShocks", "shocks", "Shocks", ClanRank.OWNER),
	BIG_STRIKE("big_strike", "glowBigStrike", "bigstrike", "Big strike", ClanRank.OWNER);

	/** sent to other party members; never change one once released */
	public final String id;
	/** the checkbox's key in {@link com.corclan.CorClanConfig} */
	public final String configKey;
	/** its name in ::myglow, e.g. ::myglow cloud off */
	public final String shortName;
	/** shown next to its checkbox in the side panel */
	public final String label;
	/** lowest rank that unlocks it */
	public final ClanRank rank;

	GlowEffect(String id, String configKey, String shortName, String label, ClanRank rank)
	{
		this.id = id;
		this.configKey = configKey;
		this.shortName = shortName;
		this.label = label;
		this.rank = rank;
	}

	public boolean unlockedBy(ClanRank wearer)
	{
		return wearer != null && wearer.getRank() >= rank.getRank();
	}

	/** The effect with id {@code id}, or null (e.g. one added by a newer plugin version). */
	public static GlowEffect byId(String id)
	{
		for (GlowEffect effect : values())
		{
			if (effect.id.equals(id))
			{
				return effect;
			}
		}
		return null;
	}

	/** The effect called {@code name} in ::myglow (any case), or null. */
	public static GlowEffect byShortName(String name)
	{
		for (GlowEffect effect : values())
		{
			if (effect.shortName.equalsIgnoreCase(name))
			{
				return effect;
			}
		}
		return null;
	}

	public static boolean isConfigKey(String key)
	{
		for (GlowEffect effect : values())
		{
			if (effect.configKey.equals(key))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * What a player of rank {@code wearer} shows.
	 * @param picks the effect ids they picked, or null if they never shared any picks (not in the CoR
	 *              party, older plugin, not received yet): then they show their own rank's effects
	 */
	public static Set<GlowEffect> active(ClanRank wearer, Collection<String> picks)
	{
		if (wearer == null)
		{
			return Collections.emptySet();
		}
		Set<GlowEffect> active = EnumSet.noneOf(GlowEffect.class);
		if (picks == null)
		{
			for (GlowEffect effect : values())
			{
				if (effect.rank.getRank() == wearer.getRank())
				{
					active.add(effect);
				}
			}
			return active;
		}
		for (String id : picks)
		{
			GlowEffect effect = byId(id);
			if (effect != null && effect.unlockedBy(wearer))
			{
				active.add(effect);
			}
		}
		return active;
	}
}

package com.corclan.glow;

import com.corclan.CorClanConfig;
import com.corclan.icons.MemberCosmetics;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanChannelMember;
import net.runelite.api.clan.ClanRank;

/**
 * Which glow effects each player shows: your own from your glow settings, everyone else's from the
 * CoR party (players outside the party, or who haven't sent picks yet, show their rank's defaults).
 * Always limited to what the wearer's clan rank, as this client sees it, unlocks. Client thread only.
 */
@Singleton
public class GlowPicks
{
	private final Client client;
	private final CorClanConfig config;
	/** member key -> picked effect ids, from party messages */
	private final Map<String, List<String>> partyPicks = new HashMap<>();
	/** party member id -> member key, so picks go when the member leaves */
	private final Map<Long, String> partyNames = new HashMap<>();

	@Inject
	GlowPicks(Client client, CorClanConfig config)
	{
		this.client = client;
		this.config = config;
	}

	/** The effect ids you switched on, locked ones included (the viewer filters by rank). */
	public List<String> localPicks()
	{
		List<String> ids = new ArrayList<>();
		for (GlowEffect effect : GlowEffect.values())
		{
			if (picked(config, effect))
			{
				ids.add(effect.id);
			}
		}
		return ids;
	}

	public static boolean picked(CorClanConfig config, GlowEffect effect)
	{
		switch (effect)
		{
			case GOLD_OUTLINE:
				return config.glowGoldOutline();
			case STORM_CLOUD:
				return config.glowStormCloud();
			case LIGHTNING_STRIKES:
				return config.glowLightningStrikes();
			case SHOCKS:
				return config.glowShocks();
			case BIG_STRIKE:
				return config.glowBigStrike();
			default:
				return false;
		}
	}

	/** A party member's picks arrived (replacing any earlier ones). */
	public void setPartyPicks(long memberId, String name, List<String> glows)
	{
		String key = MemberCosmetics.key(name);
		String old = partyNames.put(memberId, key);
		if (old != null && !old.equals(key))
		{
			partyPicks.remove(old);
		}
		partyPicks.put(key, glows == null ? new ArrayList<>() : new ArrayList<>(glows));
	}

	/** A party member left: they show their rank's defaults again. */
	public void removePartyMember(long memberId)
	{
		String key = partyNames.remove(memberId);
		if (key != null)
		{
			partyPicks.remove(key);
		}
	}

	public void clearPartyPicks()
	{
		partyPicks.clear();
		partyNames.clear();
	}

	/** Your own clan rank, or null when not in a clan (or not loaded yet). */
	public ClanRank localRank()
	{
		Player me = client.getLocalPlayer();
		ClanChannel channel = client.getClanChannel();
		if (me == null || me.getName() == null || channel == null)
		{
			return null;
		}
		ClanChannelMember member = channel.findMember(me.getName());
		return member == null ? null : member.getRank();
	}

	/** The effects {@code player} shows, empty if they aren't in the clan. */
	public Set<GlowEffect> effectsFor(ClanChannel channel, Player player)
	{
		if (channel == null || player == null || !player.isClanMember() || player.getName() == null)
		{
			return Collections.emptySet();
		}
		ClanChannelMember member = channel.findMember(player.getName());
		if (member == null)
		{
			return Collections.emptySet();
		}
		List<String> picks = player == client.getLocalPlayer()
			? localPicks()
			: partyPicks.get(MemberCosmetics.key(player.getName()));
		return GlowEffect.active(member.getRank(), picks);
	}
}

package com.corclan.glow;

import java.awt.Color;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

/**
 * How a rank's glow is drawn: stacked outlines, outermost first. Each layer is one
 * ModelOutlineRenderer pass. Pure Java so the look (including the animation) can be unit tested.
 */
public final class GlowStyle
{
	/** One outline pass. */
	public static final class Layer
	{
		public final int width;
		public final Color color;
		/** 0 (hard edge) to 4 (softest) */
		public final int feather;

		Layer(int width, Color color, int feather)
		{
			this.width = width;
			this.color = color;
			this.feather = feather;
		}
	}

	/** One slow breath of the Owner's aura: it swells and brightens, then settles. */
	static final long HOLY_PULSE_MILLIS = 3000L;
	/** The core edge's quicker white/gold shimmer. */
	static final long HOLY_SHIMMER_MILLIS = 900L;

	private GlowStyle()
	{
	}

	/**
	 * The Owner's holy glow: a wide gold aura that breathes (swelling and brightening), a bright
	 * golden-white glow inside it, and a crisp edge on the model that shimmers white to pale gold.
	 * @param now current time in millis; drives the animation
	 */
	public static List<Layer> holy(long now)
	{
		double breath = breath(now, HOLY_PULSE_MILLIS);
		double shimmer = breath(now, HOLY_SHIMMER_MILLIS);
		return Collections.unmodifiableList(Arrays.asList(
			new Layer(lerp(10, 15, breath), new Color(255, 190, 40, lerp(110, 200, breath)), 4),
			new Layer(6, new Color(255, 225, 120, lerp(210, 255, breath)), 2),
			new Layer(2, new Color(255, lerp(255, 240, shimmer), lerp(255, 170, shimmer), 255), 0)));
	}

	/** 0..1..0 over one period, eased (sine) so it breathes rather than blinks. */
	static double breath(long now, long periodMillis)
	{
		double phase = (now % periodMillis) / (double) periodMillis;
		return (1 - Math.cos(phase * 2 * Math.PI)) / 2;
	}

	private static int lerp(int from, int to, double t)
	{
		return (int) Math.round(from + (to - from) * t);
	}
}

package com.corclan.glow;

import com.corclan.CorClanConfig;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.gameval.SpotanimID;

/**
 * The Owner storm effects, on top of {@link RankGlowOverlay}'s outline: an upside-down cloud overhead
 * ({@link StormCloud}), frequent lightning strikes, electric shocks, and a rare big strike, each at
 * random moments, on every player whose picks ({@link GlowPicks}) include them. Graphics come from
 * the game cache. Drawn by this client only: players without the plugin never see them. All methods
 * must run on the client thread.
 */
@Singleton
public class HolyAura
{
	/** One graphic replayed at random intervals in its own spot-anim slot. */
	public static final class Effect
	{
		/** chat command that previews / swaps this effect, e.g. "glowzap" for ::glowzap */
		public final String command;
		public final String label;
		/** the glow setting that switches it on for a wearer */
		final GlowEffect glow;
		/** our own slot, so we never replace a graphic the game is playing on the player */
		final int slot;
		/** random gap between plays, in game ticks (0.6 s each), inclusive */
		final int minTicks;
		final int maxTicks;
		public final int defaultSpotAnimId;
		int spotAnimId;
		int nextTick;

		Effect(String command, String label, GlowEffect glow, int slot, int spotAnimId, int minTicks, int maxTicks)
		{
			this.command = command;
			this.label = label;
			this.glow = glow;
			this.slot = slot;
			this.defaultSpotAnimId = spotAnimId;
			this.spotAnimId = spotAnimId;
			this.minTicks = minTicks;
			this.maxTicks = maxTicks;
			this.nextTick = minTicks;
		}

		/** Ticks until the next play: uniformly minTicks..maxTicks, so it never falls into a rhythm. */
		int delay(Random random)
		{
			return minTicks + random.nextInt(maxTicks - minTicks + 1);
		}
	}

	/** Frequent: the Hallowed Sepulchre statue's lightning strike, every 1.2 - 3.6 s. */
	final Effect strikes = new Effect("glowzap", "strikes", GlowEffect.LIGHTNING_STRIKES, 3083, SpotanimID.HALLOWED_STATUE_LIGHTNING_STRIKE, 2, 6);
	/** The Killerwatts' electric shock crackling on the body, every 1.8 - 4.8 s. */
	final Effect shock = new Effect("glowshock", "shock", GlowEffect.SHOCKS, 3084, SpotanimID.SKELETON_KILLERWATT_ELECTRICSHOCK, 3, 8);
	/** Rare: Lucien's lightning, every 10 - 20 s. */
	final Effect bigStrike = new Effect("glowstrike", "big strike", GlowEffect.BIG_STRIKE, 3082, SpotanimID.LUC2_LUCIEN_LIGHTNING_SPOT, 17, 33);

	final List<Effect> effects = Collections.unmodifiableList(Arrays.asList(strikes, shock, bigStrike));

	private final Client client;
	private final CorClanConfig config;
	private final StormCloud cloud;
	private final GlowPicks picks;
	private final Random random = new Random();
	private int ticks;
	/** Players in view and the storm effects they show, as of the last game tick. */
	private final Map<Player, Set<GlowEffect>> wearers = new HashMap<>();

	@Inject
	HolyAura(Client client, CorClanConfig config, StormCloud cloud, GlowPicks picks)
	{
		this.client = client;
		this.config = config;
		this.cloud = cloud;
		this.picks = picks;
	}

	public void onGameTick()
	{
		if (!config.rankGlow())
		{
			return;
		}
		ticks++;
		findWearers();
		List<Player> cloudy = new ArrayList<>();
		wearers.forEach((player, shown) ->
		{
			if (shown.contains(GlowEffect.STORM_CLOUD))
			{
				cloudy.add(player);
			}
		});
		cloud.update(cloudy);

		for (Effect effect : effects)
		{
			if (ticks < effect.nextTick)
			{
				continue;
			}
			effect.nextTick = ticks + effect.delay(random);
			wearers.forEach((player, shown) ->
			{
				if (shown.contains(effect.glow))
				{
					player.createSpotAnim(effect.slot, effect.spotAnimId, 0, 0);
				}
			});
		}
	}

	/** Every client frame (20 ms): keeps the cloud over its Owner as they move. */
	public void onClientTick()
	{
		if (config.rankGlow())
		{
			cloud.follow();
		}
	}

	private void findWearers()
	{
		wearers.clear();
		ClanChannel channel = client.getClanChannel();
		for (Player player : client.getTopLevelWorldView().players())
		{
			Set<GlowEffect> shown = picks.effectsFor(channel, player);
			if (!shown.isEmpty())
			{
				wearers.put(player, shown);
			}
		}
	}

	/** The effect previewed by chat command {@code command} (without "::"), or null. */
	public Effect forCommand(String command)
	{
		for (Effect effect : effects)
		{
			if (effect.command.equals(command))
			{
				return effect;
			}
		}
		return null;
	}

	/** Plays {@code id} on your own character now and uses it for {@code effect} this session. */
	public void preview(Effect effect, int id)
	{
		effect.spotAnimId = id;
		Player me = client.getLocalPlayer();
		if (me != null)
		{
			me.createSpotAnim(effect.slot, id, 0, 0);
		}
	}

	/** Removes the cloud and our graphics from everyone (glow turned off or plugin stopped). */
	public void clear()
	{
		wearers.clear();
		cloud.clear();
		for (Player player : client.getTopLevelWorldView().players())
		{
			if (player != null)
			{
				for (Effect effect : effects)
				{
					player.removeSpotAnim(effect.slot);
				}
			}
		}
	}
}

package com.corclan.glow;

import com.corclan.CorClanConfig;
import com.corclan.icons.MemberCosmetics;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.gameval.SpotanimID;

/**
 * Lavasockz's aura, built in by name like his founder and dev icons: the Flames of Zamorak burning around him
 * nonstop, restarted the moment each play ends, so it keeps going while he walks, on top of the molten outline
 * drawn by {@link SignatureGlowOverlay}. Every plugin user sees it
 * (no party needed) while "Show clan rank glows" is on. Lavasockz can switch it off ({@link DevGlow}); other
 * players see his choice once it arrives through the CoR party, and the flames until then.
 * Graphics come from the game cache; drawn on this client only. All methods must run on the client thread.
 */
@Singleton
public class LavaAura
{
	/** Players who wear the aura, as {@link MemberCosmetics#key} names. */
	public static final Set<String> WEARERS = Collections.singleton("lavasockz");

	/** Our own spot-anim slot (Ray's storm uses 3082-3084), so we never replace a graphic the game is playing. */
	static final int SLOT = 3090;
	static final int FLAMES = SpotanimID.ZAMORAK_FLAME;

	private final Client client;
	private final CorClanConfig config;
	/** wearer key -> the parts they shared through the CoR party */
	private final Map<String, List<String>> partyPicks = new HashMap<>();
	/** party member id -> wearer key, so picks go when the member leaves */
	private final Map<Long, String> partyNames = new HashMap<>();

	@Inject
	LavaAura(Client client, CorClanConfig config)
	{
		this.client = client;
		this.config = config;
	}

	/** True for a clan member whose name wears the aura. */
	static boolean wears(Player player)
	{
		return player != null && player.isClanMember() && player.getName() != null
			&& WEARERS.contains(MemberCosmetics.key(player.getName()));
	}

	/** The parts of the aura {@code player} shows: empty unless they wear it. Client thread. */
	public Set<DevGlow> effectsFor(Player player)
	{
		if (!wears(player))
		{
			return Collections.emptySet();
		}
		if (player == client.getLocalPlayer())
		{
			Set<DevGlow> mine = EnumSet.noneOf(DevGlow.class);
			for (DevGlow glow : DevGlow.values())
			{
				if (DevGlow.picked(config, glow))
				{
					mine.add(glow);
				}
			}
			return mine;
		}
		return DevGlow.active(partyPicks.get(MemberCosmetics.key(player.getName())));
	}

	/** The parts this client's player switched on, as ids for the party message. */
	public List<String> localPicks()
	{
		List<String> ids = new ArrayList<>();
		for (DevGlow glow : DevGlow.values())
		{
			if (DevGlow.picked(config, glow))
			{
				ids.add(glow.id);
			}
		}
		return ids;
	}

	/** A party member's glow picks arrived; only wearers' are kept. */
	public void setPartyPicks(long memberId, String name, List<String> glows)
	{
		String key = MemberCosmetics.key(name);
		if (!WEARERS.contains(key))
		{
			return;
		}
		partyNames.put(memberId, key);
		partyPicks.put(key, glows == null ? new ArrayList<>() : new ArrayList<>(glows));
	}

	public void removePartyMember(long memberId)
	{
		String key = partyNames.remove(memberId);
		if (key != null)
		{
			partyPicks.remove(key);
		}
	}

	public void clearPartyPicks()
	{
		partyPicks.clear();
		partyNames.clear();
	}

	/**
	 * Every client frame (20 ms): the game drops a spot anim from its slot when it finishes, so an empty slot
	 * means the flames just ended and start again straight away. Spot anims ride on the player, so they follow
	 * him as he walks. Anyone who switched the flames off has them removed.
	 */
	public void onClientTick()
	{
		if (!config.rankGlow())
		{
			return;
		}
		for (Player player : client.getTopLevelWorldView().players())
		{
			if (!wears(player))
			{
				continue;
			}
			boolean on = effectsFor(player).contains(DevGlow.ZAMORAK_FLAMES);
			boolean playing = player.getSpotAnims().get(SLOT) != null;
			if (on && !playing)
			{
				player.createSpotAnim(SLOT, FLAMES, 0, 0);
			}
			else if (!on && playing)
			{
				player.removeSpotAnim(SLOT);
			}
		}
	}

	/** ::lavafx: plays the flames on your own character once, to show them off. */
	public void preview()
	{
		Player me = client.getLocalPlayer();
		if (me != null)
		{
			me.createSpotAnim(SLOT, FLAMES, 0, 0);
		}
	}

	/** Removes our flames from everyone (glows turned off or plugin stopped). */
	public void clear()
	{
		for (Player player : client.getTopLevelWorldView().players())
		{
			if (player != null)
			{
				player.removeSpotAnim(SLOT);
			}
		}
	}
}

package com.corclan.glow;

import java.awt.Color;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

/**
 * Lavasockz's molten outline: a dark red heat haze, an orange body of flame and a white-hot core, all
 * flickering like a fire rather than breathing like the Owner's gold glow. Pure Java so it can be tested.
 */
public final class MoltenStyle
{
	private MoltenStyle()
	{
	}

	/** @param now current time in millis; drives the flicker */
	public static List<GlowStyle.Layer> molten(long now)
	{
		double flicker = flicker(now);
		double fast = flicker(now * 3 + 1234);
		return Collections.unmodifiableList(Arrays.asList(
			new GlowStyle.Layer(lerp(9, 14, flicker), new Color(150, lerp(10, 30, fast), 0, lerp(120, 190, flicker)), 4),
			new GlowStyle.Layer(lerp(4, 6, fast), new Color(255, lerp(80, 130, flicker), 0, 235), 2),
			new GlowStyle.Layer(2, new Color(255, lerp(200, 245, fast), lerp(60, 170, fast), 255), 0)));
	}

	/**
	 * 0..1, irregular like flames: three sines at unrelated speeds added together, so it never settles
	 * into an obvious rhythm.
	 */
	static double flicker(long now)
	{
		double t = now / 1000.0;
		double v = Math.sin(t * 7.3) + 0.6 * Math.sin(t * 13.1 + 1.7) + 0.4 * Math.sin(t * 23.9 + 4.2);
		return (v / 2.0 + 1) / 2;
	}

	private static int lerp(int from, int to, double t)
	{
		double clamped = Math.max(0, Math.min(1, t));
		return (int) Math.round(from + (to - from) * clamped);
	}
}

package com.corclan.glow;

import com.corclan.CorClanConfig;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.clan.ClanChannel;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

/**
 * Outlines clan members in the game world by the glow they picked ({@link GlowPicks}). Drawn on this
 * client only; players without the plugin see nothing.
 * For now the only outline is the Owner's {@link GlowStyle#holy}.
 */
public class RankGlowOverlay extends Overlay
{
	private final Client client;
	private final CorClanConfig config;
	private final ModelOutlineRenderer outlines;
	private final GlowPicks picks;

	@Inject
	RankGlowOverlay(Client client, CorClanConfig config, ModelOutlineRenderer outlines, GlowPicks picks)
	{
		this.client = client;
		this.config = config;
		this.outlines = outlines;
		this.picks = picks;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.rankGlow())
		{
			return null;
		}
		ClanChannel channel = client.getClanChannel();
		if (channel == null)
		{
			return null;
		}
		long now = System.currentTimeMillis();
		for (Player player : client.getTopLevelWorldView().players())
		{
			if (picks.effectsFor(channel, player).contains(GlowEffect.GOLD_OUTLINE))
			{
				for (GlowStyle.Layer layer : GlowStyle.holy(now))
				{
					outlines.drawOutline(player, layer.width, layer.color, layer.feather);
				}
			}
		}
		return null;
	}
}

