import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;
import net.runelite.client.util.ImageUtil;

/** Draws CoR party members who share their position on the in-game world map. Call on the client thread. */
@Singleton
public class ClanMapPoints
{
	private final WorldMapPointManager worldMapPointManager;
	private final BufferedImage icon;
	private final List<WorldMapPoint> points = new ArrayList<>();

	@Inject
	ClanMapPoints(WorldMapPointManager worldMapPointManager)
	{
		this.worldMapPointManager = worldMapPointManager;
		// the same red rhino shown for CoR Clan in the Plugin Hub
		this.icon = ImageUtil.loadImageResource(ClanMapPoints.class, "/com/corclan/map_marker.png");
	}

	/**
	 * Replaces every marker, plus your own marker labelled "You" so you can see sharing is on even when
	 * nobody else is on the map.
	 *
	 * @param others name -> latest position
	 * @param self your own position, or null when you are not sharing
	 */
	public void update(Map<String, CorLocation> others, CorLocation self)
	{
		clear();
		if (self != null)
		{
			int n = others.size();
			add(self, "You", "You: sharing with the CoR party, " + n + (n == 1 ? " clanmate" : " clanmates") + " on the map");
		}
		others.forEach((name, loc) -> add(loc, name, name + " (W" + loc.getWorld() + ")" + (loc.isWilderness() ? ", Wilderness" : "")));
	}

	private void add(CorLocation p, String label, String tooltip)
	{
		WorldMapPoint point = WorldMapPoint.builder()
			.worldPoint(new WorldPoint(p.getX(), p.getY(), p.getPlane()))
			.image(icon)
			.name(label)
			.tooltip(tooltip)
			.snapToEdge(true)
			.jumpOnClick(true)
			.build();
		worldMapPointManager.add(point);
		points.add(point);
	}

	public void clear()
	{
		for (WorldMapPoint point : points)
		{
			worldMapPointManager.remove(point);
		}
		points.clear();
	}
}

package com.corclan.map;

/** When a player's own position may be sent to the clan map. Pure logic, unit tested. */
public final class LocationRules
{
	public enum Decision
	{
		/** send the position */
		SEND,
		/** inside the Wilderness and "Share in Wilderness" is off */
		HIDE_WILDERNESS,
		/** inside an instance (raids, some bosses), where coordinates are not real map tiles */
		HIDE_INSTANCE
	}

	private LocationRules()
	{
	}

	public static Decision decide(boolean inWilderness, boolean inInstance, boolean wildernessAllowed)
	{
		if (inInstance)
		{
			return Decision.HIDE_INSTANCE;
		}
		if (inWilderness && !wildernessAllowed)
		{
			return Decision.HIDE_WILDERNESS;
		}
		return Decision.SEND;
	}
}

package com.corclan.map;

/**
 * What the clan map is doing for this player, shown in the panel and announced in chat when it changes,
 * so it is obvious whether sharing works even when nobody else is on the map. Pure logic, unit tested.
 */
public enum MapState
{
	/** "Share my location" is off */
	OFF("Clan map: off (turn on 'Share my location')", null),
	/** sharing is on but you are not in the CoR party (or are in another party) */
	NEED_PARTY("Clan map: press Join CoR party in the CoR panel to share",
		"CoR: press Join CoR party in the CoR side panel to share your location on the clan map."),
	/** in the CoR party but not connected yet */
	CONNECTING("Clan map: connecting to the CoR party", null),
	PAUSED_WILDERNESS("Clan map: paused in the Wilderness",
		"CoR: location sharing paused in the Wilderness. Turn on 'Share in Wilderness' to keep sharing."),
	PAUSED_INSTANCE("Clan map: paused inside an instance",
		"CoR: location sharing paused inside this instance."),
	SHARING("Clan map: sharing",
		"CoR: sharing your location with the CoR party. Open the world map to see yourself (the rhino marked You).");

	/** panel line; {@link #SHARING} adds the clanmate count */
	public final String status;
	/** local game message when this state starts, or null for none */
	public final String announcement;

	MapState(String status, String announcement)
	{
		this.status = status;
		this.announcement = announcement;
	}

	public static MapState of(boolean shareLocation, boolean inCorParty, boolean partyConnected, LocationRules.Decision decision)
	{
		if (!shareLocation)
		{
			return OFF;
		}
		if (!inCorParty)
		{
			return NEED_PARTY;
		}
		if (!partyConnected)
		{
			return CONNECTING;
		}
		switch (decision)
		{
			case HIDE_WILDERNESS:
				return PAUSED_WILDERNESS;
			case HIDE_INSTANCE:
				return PAUSED_INSTANCE;
			default:
				return SHARING;
		}
	}

	/** Panel line, e.g. "Clan map: sharing, 2 clanmates on the map". */
	public String status(int clanmates)
	{
		if (this != SHARING)
		{
			return status;
		}
		return status + ", " + clanmates + (clanmates == 1 ? " clanmate" : " clanmates") + " on the map";
	}
}

