	private static final SimpleDateFormat WEEK_DAY = new SimpleDateFormat("EEE d MMM");

	static
	{
		// weeks start Sunday 00:00 UTC; show that day, not the local day before it
		WEEK_DAY.setTimeZone(TimeZone.getTimeZone("UTC"));
	}

