public class GlowEffectTest
{
	private static final ClanRank CAPTAIN = new ClanRank(5);

	@Test
	public void playersWhoNeverPickedShowTheirOwnRanksEffects()
	{
		assertEquals(EnumSet.allOf(GlowEffect.class), GlowEffect.active(ClanRank.OWNER, null));
		assertTrue(GlowEffect.active(CAPTAIN, null).isEmpty());
		assertTrue(GlowEffect.active(ClanRank.GUEST, null).isEmpty());
	}

	@Test
	public void picksAreLimitedToWhatTheWearersRankUnlocks()
	{
		assertEquals(EnumSet.of(GlowEffect.GOLD_OUTLINE, GlowEffect.SHOCKS),
			GlowEffect.active(ClanRank.OWNER, Arrays.asList("gold_outline", "shocks")));
		// a Captain (or a forged request) picking Owner effects shows nothing
		assertTrue(GlowEffect.active(CAPTAIN, Arrays.asList("gold_outline", "storm_cloud")).isEmpty());
		assertTrue(GlowEffect.active(ClanRank.DEPUTY_OWNER, Collections.singletonList("storm_cloud")).isEmpty());
	}

	@Test
	public void emptyPicksMeanNothingAndUnknownIdsAreIgnored()
	{
		assertTrue(GlowEffect.active(ClanRank.OWNER, Collections.emptyList()).isEmpty());
		assertEquals(EnumSet.of(GlowEffect.BIG_STRIKE),
			GlowEffect.active(ClanRank.OWNER, Arrays.asList("rainbow_from_the_future", "big_strike")));
		assertTrue(GlowEffect.active(null, null).isEmpty());
	}

	@Test
	public void higherRanksUnlockLowerRanksEffects()
	{
		assertTrue(GlowEffect.GOLD_OUTLINE.unlockedBy(ClanRank.OWNER));
		assertTrue(GlowEffect.GOLD_OUTLINE.unlockedBy(ClanRank.JMOD));
		assertTrue(!GlowEffect.GOLD_OUTLINE.unlockedBy(ClanRank.DEPUTY_OWNER));
	}

	@Test
	public void idsAndConfigKeysAreUniqueAndRoundTrip()
	{
		Set<String> ids = new HashSet<>();
		Set<String> keys = new HashSet<>();
		for (GlowEffect effect : GlowEffect.values())
		{
			assertTrue(ids.add(effect.id));
			assertTrue(keys.add(effect.configKey));
			assertSame(effect, GlowEffect.byId(effect.id));
			assertTrue(GlowEffect.isConfigKey(effect.configKey));
			assertSame(effect, GlowEffect.byShortName(effect.shortName.toUpperCase()));
		}
		assertNull(GlowEffect.byId("nope"));
		assertNull(GlowEffect.byShortName("nope"));
		assertTrue(!GlowEffect.isConfigKey("rankGlow"));
	}
}

package com.corclan.glow;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.awt.Color;
import java.util.List;
import org.junit.Test;

public class GlowStyleTest
{
	private static final long P = GlowStyle.HOLY_PULSE_MILLIS;

	@Test
	public void breathGoesDimToBrightToDim()
	{
		assertEquals(0.0, GlowStyle.breath(0, P), 1e-9);
		assertEquals(1.0, GlowStyle.breath(P / 2, P), 1e-9);
		assertEquals(0.0, GlowStyle.breath(P, P), 1e-9);
		for (long t = 0; t < 2 * P; t += 37)
		{
			double b = GlowStyle.breath(t, P);
			assertTrue(b >= 0 && b <= 1);
		}
	}

	@Test
	public void holyGlowIsGoldAuraDownToCrispCore()
	{
		for (long t = 0; t < 2 * P; t += 113)
		{
			List<GlowStyle.Layer> layers = GlowStyle.holy(t);
			assertEquals(3, layers.size());
			// drawn outermost first: widths shrink, the edge is hard and fully opaque
			assertTrue(layers.get(0).width > layers.get(1).width && layers.get(1).width > layers.get(2).width);
			assertEquals(0, layers.get(2).feather);
			assertEquals(255, layers.get(2).color.getAlpha());
			for (GlowStyle.Layer layer : layers)
			{
				assertTrue(layer.feather >= 0 && layer.feather <= 4);
				// gold: red channel full, blue channel lowest
				assertEquals(255, layer.color.getRed());
				assertTrue(layer.color.getBlue() <= layer.color.getGreen());
			}
		}
	}

	@Test
	public void auraSwellsAndBrightensWithEachBreath()
	{
		GlowStyle.Layer rest = GlowStyle.holy(0).get(0);
		GlowStyle.Layer peak = GlowStyle.holy(P / 2).get(0);
		assertTrue(peak.width > rest.width);
		assertTrue(peak.color.getAlpha() > rest.color.getAlpha());
		// bright even at rest
		assertTrue(rest.color.getAlpha() >= 100);
	}

	@Test
	public void coreShimmersWhiteToPaleGold()
	{
		Color white = GlowStyle.holy(0).get(2).color;
		Color gold = GlowStyle.holy(GlowStyle.HOLY_SHIMMER_MILLIS / 2).get(2).color;
		assertEquals(new Color(255, 255, 255, 255), white);
		assertTrue(gold.getBlue() < white.getBlue());
	}
}

package com.corclan.glow;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.util.HashSet;
import java.util.Random;
import java.util.Set;
import java.util.stream.Collectors;
import net.runelite.api.gameval.SpotanimID;
import org.junit.Test;

public class HolyAuraTest
{
	private static final HolyAura AURA = new HolyAura(null, null, null, null);

	private static void assertDelaysCoverRange(HolyAura.Effect effect)
	{
		Random random = new Random(42);
		Set<Integer> seen = new HashSet<>();
		for (int i = 0; i < 2000; i++)
		{
			int d = effect.delay(random);
			assertTrue(d >= effect.minTicks && d <= effect.maxTicks);
			seen.add(d);
		}
		// every gap in the range turns up, so effects don't fall into a fixed rhythm
		assertEquals(effect.maxTicks - effect.minTicks + 1, seen.size());
	}

	@Test
	public void theStormLayers()
	{
		assertEquals(SpotanimID.HALLOWED_STATUE_LIGHTNING_STRIKE, AURA.strikes.spotAnimId);
		assertEquals(SpotanimID.SKELETON_KILLERWATT_ELECTRICSHOCK, AURA.shock.spotAnimId);
		assertEquals(SpotanimID.LUC2_LUCIEN_LIGHTNING_SPOT, AURA.bigStrike.spotAnimId);
	}

	@Test
	public void randomLayersVaryWithinTheirRanges()
	{
		assertDelaysCoverRange(AURA.strikes);
		assertDelaysCoverRange(AURA.shock);
		assertDelaysCoverRange(AURA.bigStrike);
		// frequent strikes every 1.2 - 3.6 s, the big one every 10 - 20 s (0.6 s per tick)
		assertEquals(2, AURA.strikes.minTicks);
		assertEquals(6, AURA.strikes.maxTicks);
		assertTrue(AURA.bigStrike.minTicks * 0.6 >= 10 && AURA.bigStrike.maxTicks * 0.6 <= 20);
	}

	@Test
	public void everyLayerHasItsOwnSlotAndCommand()
	{
		assertEquals(AURA.effects.size(), AURA.effects.stream().map(e -> e.slot).collect(Collectors.toSet()).size());
		assertSame(AURA.strikes, AURA.forCommand("glowzap"));
		assertSame(AURA.shock, AURA.forCommand("glowshock"));
		assertSame(AURA.bigStrike, AURA.forCommand("glowstrike"));
		assertNull(AURA.forCommand("glowcloud"));
		assertNull(AURA.forCommand("cor"));
	}
}

